$_SESSION['csrf']??=bin2hex(random_bytes(32));$notice=(string)($_SESSION['admin_notice']??'');unset($_SESSION['admin_notice']);
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!hash_equals((string)$_SESSION['csrf'],(string)($_POST['csrf']??''))){http_response_code(403);exit('Your session expired.');}
    try{$action=(string)($_POST['action']??'');
        if($action==='save_whatsapp'){$phoneId=trim((string)($_POST['whatsapp_phone_number_id']??''));$businessId=trim((string)($_POST['whatsapp_business_account_id']??''));$version=trim((string)($_POST['whatsapp_api_version']??'v20.0'));$template=trim((string)($_POST['whatsapp_template']??'venue_enquiry_confirmation'));$token=trim((string)($_POST['whatsapp_access_token']??''));if($phoneId===''||!preg_match('/^[0-9]+$/',$phoneId))throw new InvalidArgumentException('Enter a valid WhatsApp Phone Number ID.');if($businessId!==''&&!preg_match('/^[0-9]+$/',$businessId))throw new InvalidArgumentException('Business Account ID must contain digits only.');if(!preg_match('/^v[0-9]+\.[0-9]+$/',$version))throw new InvalidArgumentException('Use a Graph API version such as v20.0.');if($template===''||admin_text_length($template)>120||!preg_match('/^[a-z0-9_]+$/',$template))throw new InvalidArgumentException('Enter a valid approved template name.');if($token!==''&&admin_text_length($token)>500)throw new InvalidArgumentException('Access token is too long.');setting_save($db,'whatsapp_phone_number_id',$phoneId,'whatsapp');setting_save($db,'whatsapp_business_account_id',$businessId,'whatsapp');setting_save($db,'whatsapp_api_version',$version,'whatsapp');setting_save($db,'whatsapp_template',$template,'whatsapp');if($token!=='')setting_save($db,'whatsapp_access_token_enc',booking_encrypt_resend_key($token,$config),'whatsapp');$_SESSION['admin_notice']='WhatsApp Cloud API settings saved. The token is encrypted and never displayed.';header('Location: whatsapp.php');exit;}
        if($action==='test_whatsapp'){$phoneId=setting($db,'whatsapp_phone_number_id');$version=setting($db,'whatsapp_api_version','v20.0');$token=booking_whatsapp_token($db,$config);if($phoneId===''||$token==='')throw new RuntimeException('Save the Phone Number ID and access token first.');if(!function_exists('curl_init'))throw new RuntimeException('PHP cURL is required for the WhatsApp Cloud API.');$ch=curl_init('https://graph.facebook.com/'.rawurlencode($version).'/'.rawurlencode($phoneId).'?fields=display_phone_number,verified_name');curl_setopt_array($ch,[CURLOPT_RETURNTRANSFER=>true,CURLOPT_TIMEOUT=>15,CURLOPT_HTTPHEADER=>['Authorization: Bearer '.$token]]);$body=curl_exec($ch);$code=(int)curl_getinfo($ch,CURLINFO_HTTP_CODE);curl_close($ch);if($body===false||$code<200||$code>=300)throw new RuntimeException('WhatsApp API connection failed. Check the token, Phone Number ID and API version.');$_SESSION['admin_notice']='WhatsApp Cloud API connection successful.';header('Location: whatsapp.php');exit;}
    }catch(Throwable $e){$_SESSION['admin_notice']=$e->getMessage();header('Location: whatsapp.php');exit;}
}
